INSERT OR IGNORE INTO tests (id, title, description, kind, current_version, created_at, updated_at) VALUES (1, 'Pretest — The skeletal muscle', 'Check what you already know before the session.', 'pretest', 1, '2026-09-10T02:00:00.000Z', '2026-09-10T02:00:00.000Z');
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (1, 1, 1, 'single', 'Which type of muscle tissue is under voluntary control?', NULL, '[{"id":"a","text":"Skeletal muscle"},{"id":"b","text":"Cardiac muscle"},{"id":"c","text":"Smooth muscle"},{"id":"d","text":"All three types"}]', '"a"', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (2, 1, 2, 'single', 'Which connective tissue surrounds an individual skeletal muscle fiber?', NULL, '[{"id":"a","text":"Epimysium"},{"id":"b","text":"Perimysium"},{"id":"c","text":"Endomysium"},{"id":"d","text":"Sarcolemma"}]', '"c"', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (3, 1, 3, 'truefalse', 'Myosin is a component of the thin filament.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]', 'false', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (4, 1, 4, 'multi', 'Which proteins make up the thin filament? (select all that apply)', NULL, '[{"id":"a","text":"Actin"},{"id":"b","text":"Tropomyosin"},{"id":"c","text":"Troponin"},{"id":"d","text":"Myosin"}]', '["a","b","c"]', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (5, 1, 5, 'single', 'A sarcomere is the region between…', NULL, '[{"id":"a","text":"two M-lines"},{"id":"b","text":"two Z-discs"},{"id":"c","text":"two H-zones"},{"id":"d","text":"the A-band and the I-band"}]', '"b"', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (6, 1, 6, 'single', 'The nuclei of a skeletal muscle fiber are…', NULL, '[{"id":"a","text":"single and central"},{"id":"b","text":"multiple and peripheral"},{"id":"c","text":"single and peripheral"},{"id":"d","text":"absent"}]', '"b"', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (7, 1, 7, 'truefalse', 'During contraction, the length of the A-band stays the same.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]', 'true', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (8, 1, 8, 'single', 'Which region of the sarcomere contains only thin filaments?', NULL, '[{"id":"a","text":"A-band"},{"id":"b","text":"H-zone"},{"id":"c","text":"I-band"},{"id":"d","text":"M-line"}]', '"c"', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (9, 1, 9, 'short', 'Which ion, released from the sarcoplasmic reticulum, triggers muscle contraction?', NULL, '[]', '["Calcium","Ca2+","Ca++","Ca","Calcium ion"]', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (10, 1, 10, 'single', 'Which connective tissue wraps a fascicle (a bundle of muscle fibers)?', NULL, '[{"id":"a","text":"Perimysium"},{"id":"b","text":"Endomysium"},{"id":"c","text":"Epimysium"},{"id":"d","text":"Sarcoplasmic reticulum"}]', '"a"', 1, 1);
