INSERT OR IGNORE INTO tests (id, title, description, kind, current_version, created_at, updated_at) VALUES (2, 'Posttest — Muscular system I', 'Muscle tissue types, connective tissues and the sarcomere during contraction.', 'posttest', 1, '2026-09-10T02:00:00.000Z', '2026-09-10T02:00:00.000Z');
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (11, 2, 1, 'multi', 'Which muscle types are striated? (select all that apply)', NULL, '[{"id":"a","text":"Skeletal muscle"},{"id":"b","text":"Cardiac muscle"},{"id":"c","text":"Smooth muscle"}]', '["a","b"]', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (12, 2, 2, 'single', 'Intercalated discs (desmosomes + gap junctions) are characteristic of…', NULL, '[{"id":"a","text":"Skeletal muscle"},{"id":"b","text":"Cardiac muscle"},{"id":"c","text":"Smooth muscle"},{"id":"d","text":"All muscle types"}]', '"b"', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (13, 2, 3, 'single', 'What is the shape of a smooth muscle cell?', NULL, '[{"id":"a","text":"Long and cylindrical"},{"id":"b","text":"Short and branched"},{"id":"c","text":"Spindle-shaped (fusiform)"},{"id":"d","text":"Star-shaped"}]', '"c"', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (14, 2, 4, 'multi', 'During contraction, which of these become shorter? (select all that apply)', NULL, '[{"id":"a","text":"Sarcomere"},{"id":"b","text":"I-band"},{"id":"c","text":"H-zone"},{"id":"d","text":"A-band"},{"id":"e","text":"Thick filament"}]', '["a","b","c"]', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (15, 2, 5, 'truefalse', 'The thin and thick filaments themselves shorten during contraction.', NULL, '[{"id":"true","text":"True"},{"id":"false","text":"False"}]', 'false', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (16, 2, 6, 'single', 'Which of these structures has the largest diameter?', NULL, '[{"id":"a","text":"Myofibril"},{"id":"b","text":"Muscle fiber (cell)"},{"id":"c","text":"Thick filament"},{"id":"d","text":"Thin filament"}]', '"b"', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (17, 2, 7, 'single', 'What is the approximate diameter of a thin filament?', NULL, '[{"id":"a","text":"5–6 nm"},{"id":"b","text":"10–12 nm"},{"id":"c","text":"1–2 µm"},{"id":"d","text":"about 100 µm"}]', '"a"', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (18, 2, 8, 'short', 'Name the connective tissue layer that surrounds a whole skeletal muscle.', NULL, '[]', '["Epimysium"]', 1, 1);
INSERT OR IGNORE INTO questions (id, test_id, position, type, prompt, image_url, options, answer, points, required) VALUES (19, 2, 9, 'single', 'What does tropomyosin do in a resting muscle?', NULL, '[{"id":"a","text":"Binds ATP"},{"id":"b","text":"Covers the myosin-binding sites on actin"},{"id":"c","text":"Releases Ca2+"},{"id":"d","text":"Anchors thick filaments at the M-line"}]', '"b"', 1, 1);
